// Line-for-line port of src/countersigned/engine.py. The strings are identical on purpose:
// test/conformance.test.ts compares whole decisions, evidence text included, against
// fixtures generated by the Python engine.
import type { Json } from './canonical';

export type Scalar = boolean | number | string;
export type Params = Record<string, Scalar>;
export type Outcome = 'execute' | 'ask' | 'defer' | 'escalate' | 'refuse';
export type Reversibility = 'reversible' | 'partial' | 'irreversible';

export interface Evidence { rule: string; detail: string; source: string }
export interface Grant { operation: string; environments: string[]; max_quantity?: number | null }
export interface AgentInfo { id: string; disabled: boolean; grants: Grant[] }

export interface Facts {
  tickets?: Record<string, { kind: string; status: string }>;
  segment_sizes?: Record<string, number>;
  payments?: Record<string, { amount_cents: number; refunded_cents: number }>;
  services?: Record<string, number>;
}

/* eslint-disable @typescript-eslint/no-explicit-any */
export interface Policy {
  name: string;
  escalate_risk: number;
  approval_ttl_minutes: number;
  operations: Record<string, any>;
}

export interface StoredContext {
  now: string;
  agent: AgentInfo;
  facts: Facts;
  usage_agent: number;
  usage_global: number;
  kill_switch: boolean;
  kill_reason: string | null;
  mode: string;
  human_approved: boolean;
}

export interface Context extends StoredContext {
  policy: Policy;
  policy_version: string;
}

export interface Decision {
  outcome: Outcome;
  confidence: number;
  risk_score: number;
  reversibility: Reversibility;
  effective_quantity: number | null;
  environment: string;
  evidence: Evidence[];
  missing_information: string[];
  reasons: string[];
  retry_after: string | null;
  policy_version: string;
}

const REV_POINTS: Record<string, number> = { reversible: 0, partial: 15, irreversible: 35 };
const ENVIRONMENTS = ['staging', 'prod'];

interface Resolved {
  quantity: number | null;
  reversibility: Reversibility;
  evidence: Evidence[];
  missing: string[];
  refusals: string[];
  inconsistent: boolean;
}

const ev = (rule: string, detail: string, source: string): Evidence => ({ rule, detail, source });
const isInt = (v: unknown): v is number => typeof v === 'number' && Number.isInteger(v);
const has = (p: Params, k: string): boolean => Object.prototype.hasOwnProperty.call(p, k);
const isStr = (v: unknown): v is string => typeof v === 'string';
const newResolved = (rev: Reversibility = 'reversible'): Resolved => (
  { quantity: null, reversibility: rev, evidence: [], missing: [], refusals: [], inconsistent: false }
);

function posInt(p: Params, key: string, r: Resolved): number | null {
  if (!has(p, key)) return null; // reported by the required-fields check
  const v = p[key];
  if (!isInt(v) || v <= 0) {
    r.missing.push(`${key} must be a positive integer`);
    return null;
  }
  return v;
}

function checkTicket(p: Params, facts: Facts, spec: any, r: Resolved): void {
  const tid = p.ticket_id;
  if (!isStr(tid) || !tid) return;
  const t = facts.tickets?.[tid];
  if (t === undefined) {
    r.missing.push(`ticket ${tid} does not exist: cite a real, open ticket`);
    r.inconsistent = true;
    r.evidence.push(ev('ticket_verified', `${tid} not found`, 'fact'));
  } else if (t.status !== 'open' || t.kind !== spec.ticket_kind) {
    r.missing.push(`ticket ${tid} is ${t.status} / ${t.kind}; need an open ${spec.ticket_kind}`);
    r.inconsistent = true;
    r.evidence.push(ev('ticket_verified', `${tid} is ${t.status} ${t.kind}`, 'fact'));
  } else {
    r.evidence.push(ev('ticket_verified', `${tid} is an open ${t.kind}`, 'fact'));
  }
}

function resolveDelete(p: Params, facts: Facts, spec: any): Resolved {
  const r = newResolved();
  const claimed = posInt(p, 'count', r);
  const hard = has(p, 'hard') ? p.hard : false;
  if (hard === true) {
    r.reversibility = 'irreversible';
    r.evidence.push(ev('reversibility', 'hard delete is permanent', 'policy'));
  } else if (hard === false) {
    r.reversibility = 'reversible';
    r.evidence.push(ev('reversibility', 'soft delete can be restored', 'policy'));
  } else {
    r.missing.push('hard must be true or false');
  }
  const seg = p.segment;
  if (has(p, 'segment') && (!isStr(seg) || !seg)) {
    r.missing.push('segment must be a non-empty string');
  } else if (isStr(seg)) {
    const size = facts.segment_sizes?.[seg];
    if (size === undefined) {
      r.missing.push(`segment '${seg}' is not a known segment`);
      r.evidence.push(ev('segment_resolved', `'${seg}' unknown`, 'fact'));
    } else {
      r.evidence.push(ev('segment_resolved', `segment '${seg}' currently matches ${size} records`, 'fact'));
      if (claimed !== null) {
        r.quantity = Math.max(claimed, size);
        if (claimed !== size) {
          r.inconsistent = true;
          r.missing.push(`count must equal the ${size} records segment '${seg}' matches (agent said ${claimed})`);
          r.evidence.push(ev('claim_mismatch', `agent said ${claimed}, data says ${size}`, 'agent_claim'));
        }
      }
    }
  }
  if (r.quantity === null) r.quantity = claimed;
  checkTicket(p, facts, spec, r);
  return r;
}

function resolveExport(p: Params, facts: Facts, spec: any): Resolved {
  const r = newResolved();
  r.quantity = posInt(p, 'count', r);
  const dest = p.destination;
  const d = spec.destinations ?? {};
  if (isStr(dest) && dest) {
    if ((d.internal ?? []).includes(dest)) {
      r.reversibility = 'reversible';
      r.evidence.push(ev('destination', `${dest} is inside the perimeter`, 'policy'));
    } else if ((d.external ?? []).includes(dest)) {
      r.reversibility = 'irreversible';
      r.evidence.push(ev('destination', `${dest} is external: data cannot be recalled`, 'policy'));
    } else {
      r.reversibility = 'irreversible';
      r.refusals.push(`destination '${dest}' is not on the allow-list`);
      r.evidence.push(ev('destination', `${dest} is not allow-listed`, 'policy'));
    }
  } else if (has(p, 'destination')) {
    r.missing.push('destination must be a non-empty string');
  }
  checkTicket(p, facts, spec, r);
  return r;
}

function resolveRefund(p: Params, facts: Facts, spec: any): Resolved {
  const r = newResolved('partial');
  r.quantity = posInt(p, 'amount_cents', r);
  r.evidence.push(ev('reversibility', 'money out can only be partly recovered', 'policy'));
  const pid = p.payment_id;
  if (isStr(pid) && pid) {
    const pay = facts.payments?.[pid];
    if (pay === undefined) {
      r.missing.push(`payment ${pid} does not exist`);
      r.inconsistent = true;
      r.evidence.push(ev('payment_verified', `${pid} not found`, 'fact'));
    } else {
      const left = pay.amount_cents - pay.refunded_cents;
      r.evidence.push(ev('payment_verified', `${pid} has ${left} cents left to refund`, 'fact'));
      if (r.quantity !== null && r.quantity > left) {
        r.refusals.push(`refund of ${r.quantity} exceeds the ${left} cents still refundable on ${pid}`);
      }
    }
  } else if (has(p, 'payment_id')) {
    r.missing.push('payment_id must be a non-empty string');
  }
  checkTicket(p, facts, spec, r);
  return r;
}

function resolveTransfer(p: Params, _facts: Facts, _spec: any): Resolved {
  const r = newResolved('irreversible');
  r.quantity = posInt(p, 'amount_cents', r);
  r.evidence.push(ev('reversibility', 'transfers are final', 'policy'));
  if (has(p, 'to_account') && (!isStr(p.to_account) || !p.to_account)) {
    r.missing.push('to_account must be a non-empty string');
  }
  return r;
}

function resolveScaleDown(p: Params, facts: Facts, _spec: any): Resolved {
  const r = newResolved('reversible');
  r.evidence.push(ev('reversibility', 'replicas can be scaled back up', 'policy'));
  const frm = p.replicas_from, to = p.replicas_to;
  let ok = true;
  if (has(p, 'replicas_from') && (!isInt(frm) || frm < 0)) {
    r.missing.push('replicas_from must be a non-negative integer');
    ok = false;
  }
  if (has(p, 'replicas_to') && (!isInt(to) || to < 0)) {
    r.missing.push('replicas_to must be a non-negative integer');
    ok = false;
  }
  if (ok && isInt(frm) && isInt(to)) {
    if (to >= frm) r.missing.push('replicas_to must be lower than replicas_from');
    else r.quantity = frm - to;
  }
  const svc = p.service;
  if (isStr(svc) && svc) {
    const actual = facts.services?.[svc];
    if (actual === undefined) {
      r.missing.push(`service '${svc}' does not exist`);
      r.inconsistent = true;
    } else {
      r.evidence.push(ev('service_verified', `${svc} currently runs ${actual} replicas`, 'fact'));
      if (isInt(frm) && actual !== frm) {
        r.missing.push(`${svc} runs ${actual} replicas, not ${frm}`);
        r.inconsistent = true;
        r.evidence.push(ev('claim_mismatch', `agent said ${frm}, service has ${actual}`, 'agent_claim'));
      }
    }
  } else if (has(p, 'service')) {
    r.missing.push('service must be a non-empty string');
  }
  return r;
}

const RESOLVERS: Record<string, (p: Params, f: Facts, s: any) => Resolved> = {
  'customer_data.delete_records': resolveDelete,
  'customer_data.export_records': resolveExport,
  'payments.refund': resolveRefund,
  'payments.transfer': resolveTransfer,
  'infrastructure.scale_down': resolveScaleDown,
};

export const OPERATIONS = Object.keys(RESOLVERS);

function nextWindowStart(now: Date, startHour: number): Date {
  const t = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), startHour, 0, 0, 0));
  return t.getTime() > now.getTime() ? t : new Date(t.getTime() + 86400000);
}

export function riskScore(
  spec: any, reversibility: string, qty: number, env: string, usageAgent: number, inconsistent: boolean,
): number {
  let pts = REV_POINTS[reversibility] ?? 0;
  const auto: number = spec.limits.auto;
  if (qty > 0) pts += auto === 0 ? 30 : Math.floor((30 * Math.min(qty, 4 * auto)) / (4 * auto));
  if (spec.pii && qty > 0) pts += 10;
  if (env === 'prod') pts += 10;
  const hard: number | undefined = spec.window?.agent_hard;
  if (hard) pts += Math.floor((20 * Math.min(usageAgent + qty, hard)) / hard);
  if (inconsistent) pts += 10;
  return Math.min(100, pts);
}

const pad2 = (n: number): string => String(n).padStart(2, '0');

export function evaluate(operation: string, params: Params, ctx: Context): Decision {
  const evidence: Evidence[] = [];
  const refusals: string[] = [];
  const missing: string[] = [];
  const defers: string[] = [];
  const escalations: string[] = [];
  let retryAfter: string | null = null;

  if (ctx.kill_switch) {
    refusals.push('kill switch is on' + (ctx.kill_reason ? `: ${ctx.kill_reason}` : ''));
    evidence.push(ev('kill_switch', 'all actions are halted', 'state'));
  }
  if (ctx.agent.disabled) {
    refusals.push(`agent ${ctx.agent.id} is disabled`);
    evidence.push(ev('agent_enabled', `${ctx.agent.id} is disabled`, 'state'));
  }

  const spec = ctx.policy.operations[operation];
  if (spec === undefined || !(operation in RESOLVERS)) {
    refusals.push(`unknown operation '${operation}'`);
    evidence.push(ev('known_operation', `'${operation}' is not in policy ${ctx.policy_version}`, 'policy'));
    return {
      outcome: 'refuse', confidence: 95, risk_score: 100, reversibility: 'irreversible', effective_quantity: null,
      environment: 'prod', evidence, missing_information: [], reasons: refusals, retry_after: null,
      policy_version: ctx.policy_version,
    };
  }

  const grant = ctx.agent.grants.find((g) => g.operation === operation);
  if (grant === undefined) {
    refusals.push(`${ctx.agent.id} has no grant for ${operation}`);
    evidence.push(ev('grant', `no grant for ${operation}`, 'state'));
  }

  const envGiven = has(params, 'environment');
  let env: Scalar = envGiven ? (params.environment as Scalar) : 'prod';
  if (typeof env !== 'string' || !ENVIRONMENTS.includes(env)) {
    refusals.push("environment must be 'staging' or 'prod'");
    env = 'prod';
  } else if (grant !== undefined && !grant.environments.includes(env)) {
    refusals.push(`${ctx.agent.id} is not granted ${operation} in ${env}`);
    evidence.push(ev('grant', `${operation} not granted in ${env}`, 'state'));
  } else if (grant !== undefined) {
    evidence.push(ev('grant', `${ctx.agent.id} may ${operation} in ${env}`, 'state'));
  }
  if (!envGiven) evidence.push(ev('environment', 'not specified; assuming prod', 'policy'));

  for (const k of spec.required as string[]) {
    const v = params[k];
    if (!has(params, k) || v === null || v === undefined || v === '') missing.push(`${k} is required`);
  }

  const r = RESOLVERS[operation]!(params, ctx.facts, spec);
  evidence.push(...r.evidence);
  missing.push(...r.missing);
  refusals.push(...r.refusals);
  const qty = r.quantity;

  const lim = spec.limits;
  const win = spec.window ?? {};
  if (qty !== null) {
    if (grant !== undefined && grant.max_quantity != null && qty > grant.max_quantity) {
      refusals.push(`${qty} exceeds this agent's cap of ${grant.max_quantity}`);
      evidence.push(ev('agent_cap', `${qty} > ${grant.max_quantity}`, 'state'));
    }
    if (qty > lim.hard) {
      refusals.push(`${qty} exceeds the hard limit of ${lim.hard} per action`);
      evidence.push(ev('per_action_hard_limit', `${qty} > ${lim.hard}`, 'policy'));
    } else if (qty > lim.auto) {
      escalations.push(`${qty} exceeds the automatic limit of ${lim.auto} per action`);
      evidence.push(ev('per_action_auto_limit', `${qty} > ${lim.auto}`, 'policy'));
    } else {
      evidence.push(ev('per_action_auto_limit', `${qty} <= ${lim.auto}`, 'policy'));
    }
    const hours = win.hours ?? 24;
    const totalAgent = ctx.usage_agent + qty;
    const totalGlobal = ctx.usage_global + qty;
    if ('agent_hard' in win && totalAgent > win.agent_hard) {
      refusals.push(`${totalAgent} in ${hours}h would exceed this agent's hard cap of ${win.agent_hard}`);
      evidence.push(ev('window_agent_hard', `${ctx.usage_agent} already + ${qty} = ${totalAgent} > ${win.agent_hard}`, 'policy'));
    } else if ('agent_auto' in win && totalAgent > win.agent_auto) {
      escalations.push(`${totalAgent} in ${hours}h exceeds the automatic window limit of ${win.agent_auto} (cumulative, not per action)`);
      evidence.push(ev('window_agent_auto', `${ctx.usage_agent} already + ${qty} = ${totalAgent} > ${win.agent_auto}`, 'policy'));
    }
    if ('global_hard' in win && totalGlobal > win.global_hard) {
      refusals.push(`${totalGlobal} across all agents in ${hours}h would exceed ${win.global_hard}`);
      evidence.push(ev('window_global_hard', `${ctx.usage_global} already + ${qty} = ${totalGlobal} > ${win.global_hard}`, 'policy'));
    }
  }

  if (r.reversibility === 'irreversible') escalations.push('irreversible actions need a human');

  const cw = spec.change_window;
  if (cw && (cw.environments as string[]).includes(env)) {
    const now = new Date(ctx.now);
    const h = now.getUTCHours();
    if (!(cw.start_hour <= h && h < cw.end_hour)) {
      retryAfter = nextWindowStart(now, cw.start_hour).toISOString();
      defers.push(`${env} changes are only allowed ${pad2(cw.start_hour)}:00-${pad2(cw.end_hour)}:00 UTC`);
      evidence.push(ev('change_window', `now ${pad2(h)}:xx UTC is outside ${pad2(cw.start_hour)}-${pad2(cw.end_hour)}`, 'policy'));
    }
  }

  const q = qty ?? 0;
  const risk = riskScore(spec, r.reversibility, q, env, ctx.usage_agent, r.inconsistent);
  if (risk >= ctx.policy.escalate_risk) escalations.push(`risk score ${risk} is at or above ${ctx.policy.escalate_risk}`);

  let outcome: Outcome;
  let reasons: string[];
  if (refusals.length) { outcome = 'refuse'; reasons = refusals; }
  else if (missing.length) { outcome = 'ask'; reasons = missing; }
  else if (defers.length) { outcome = 'defer'; reasons = defers; }
  else if (escalations.length) { outcome = 'escalate'; reasons = escalations; }
  else { outcome = 'execute'; reasons = ['within every limit']; }

  if (ctx.mode === 'execute' && outcome === 'escalate' && ctx.human_approved) {
    outcome = 'execute';
    reasons = ['human approval covers: ' + escalations.join('; ')];
    evidence.push(ev('human_approval', 'a recorded approval matches this exact action', 'state'));
  }

  let conf = 100;
  if (r.inconsistent) conf -= 20;
  if (!envGiven) conf -= 5;
  if (outcome === 'execute' && qty !== null && lim.auto > 0 && qty * 100 >= 80 * lim.auto) {
    conf -= 10;
    evidence.push(ev('near_limit', `${qty} is within 20% of the automatic limit ${lim.auto}`, 'policy'));
  }
  conf = Math.max(30, conf);

  return {
    outcome, confidence: conf, risk_score: risk, reversibility: r.reversibility, effective_quantity: qty,
    environment: env, evidence, missing_information: outcome === 'ask' ? missing : [], reasons,
    retry_after: outcome === 'defer' ? retryAfter : null, policy_version: ctx.policy_version,
  };
}

export type { Json };
